CREATE OR REPLACE PROCEDURE record_attendance(p_student_id BIGINT,p_date DATE,p_status VARCHAR,p_teacher_id BIGINT,p_remarks TEXT DEFAULT NULL) LANGUAGE plpgsql AS $$ BEGIN INSERT INTO attendance(student_id,attendance_date,status,marked_by,remarks) VALUES(p_student_id,p_date,p_status,p_teacher_id,p_remarks) ON CONFLICT(student_id,attendance_date) DO UPDATE SET status=EXCLUDED.status,marked_by=EXCLUDED.marked_by,remarks=EXCLUDED.remarks; END; $$;